const GR_JA4=[
 ["Listing actions with たり","Verb た-form + り、verb た-form + りします","Make the た-form of a verb (the same as the て-form, with て changed to た and で changed to だ) and add り (ri). Use it for two actions, then end with します. It gives examples of what you do, not a complete list. 読む becomes 読んだり. 聞く becomes 聞いたり.",[["本","hon","book"],["を","o","(object)"],["読んだり","yondari","read, and"],["、","",""],["音楽","ongaku","music"],["を","o","(object)"],["聞いたり","kiitari","listen, and"],["します","shimasu","do"],["。","",""]],"I do things like read books and listen to music."],
 ["Ability with ことができます","Verb dictionary form + ことができます","The dictionary form is the form found in a dictionary, for example 話す (hanasu, “speak”). Add ことができます (koto ga dekimasu) to say “can do” or “is able to do”. 話すことができます means “can speak”.",[["私","watashi","I"],["は","wa","(topic)"],["日本語","nihongo","Japanese"],["を","o","(object)"],["話す","hanasu","speak"],["こと","koto","the act of"],["が","ga","(subject)"],["できます","dekimasu","can do"],["。","",""]],"I can speak Japanese."],
 ["Not doing with ないでください","Verb ない-form + でください","The ない-form (nai-form) is the “not” form of a verb. For verbs like 食べる, remove る and add ない: 食べない. For verbs like 行く, change the last sound く to かない: 行かない. Add でください (de kudasai) to say “please do not”.",[["窓","mado","window"],["を","o","(object)"],["開けない","akenai","do not open"],["で","de","(links to ください)"],["ください","kudasai","please"],["。","",""]],"Please do not open the window."],
 ["Must with なければなりません","Verb ない-form − い + ければなりません","To say “must”, take the ない-form of a verb, remove the last い and add ければなりません (kereba narimasen). 飲む becomes 飲まない, and then 飲まなければなりません: “must drink” or “must take”.",[["薬","kusuri","medicine"],["を","o","(object)"],["飲まなければ","nomanakereba","if I do not drink"],["なりません","narimasen","is not allowed"],["。","",""]],"I must take medicine."],
 ["Choosing between two with どちら","A と B と どちらが adjective ですか","どちら (dochira) means “which of two”. Name both things with と (to), then ask どちらが and add the adjective. The answer names the chosen thing with が: 犬が好きです.",[["犬","inu","dog"],["と","to","and"],["猫","neko","cat"],["と","to","and"],["どちら","dochira","which of two"],["が","ga","(subject)"],["好き","suki","liked"],["です","desu","is"],["か","ka","(question)"],["？","",""]],"Which do you like more, dogs or cats?"],
 ["Only with だけ","Noun or amount + だけ","だけ (dake) means “only”. Put it after a noun or an amount. 千円だけ means “only 1,000 yen”. It can replace を, as in 水だけ飲みます (“I drink only water”).",[["財布","saifu","wallet"],["に","ni","in"],["は","wa","(topic)"],["千","sen","thousand"],["円","en","yen"],["だけ","dake","only"],["あります","arimasu","there is"],["。","",""]],"There is only 1,000 yen in my wallet."],
 ["About with ごろ and ぐらい","Time + ごろ, amount + ぐらい","ごろ (goro) after a time means “about”: 三時ごろ is “about three o’clock”. ぐらい (gurai) after an amount means “about”: 十分ぐらい is “about ten minutes”.",[["三","san","three"],["時","ji","o’clock"],["ごろ","goro","about"],["駅","eki","station"],["に","ni","at"],["着きます","tsukimasu","arrive"],["。","",""]],"I will arrive at the station at about three o’clock."],
 ["After doing with てから","Verb て-form + から","て-form + から (kara) means “after doing”. The action before から happens first. 食べてから、勉強します means “after I eat, I study”.",[["ご飯","gohan","meal"],["を","o","(object)"],["食べて","tabete","eat and"],["から","kara","after"],["、","",""],["テレビ","terebi","TV"],["を","o","(object)"],["見ます","mimasu","watch"],["。","",""]],"After I eat a meal, I watch TV."],
 ["Adjectives as adverbs","い-adjective − い + く, な-adjective + に","To say how an action is done, change the adjective. For an い-adjective, change い to く: 大きい becomes 大きく. For a な-adjective, add に: 静か becomes 静かに. Then put it before the verb.",[["大きく","ookiku","big (as an adverb)"],["書いて","kaite","write and"],["ください","kudasai","please"],["。","",""]],"Please write big."],
 ["Ending with ね and よ","Sentence + ね, sentence + よ","ね (ne) at the end of a sentence asks the listener to agree: “isn’t it?”. よ (yo) gives the listener information that they may not know. いい天気ですね and いい天気ですよ are both correct. They have different meanings.",[["いい","ii","nice"],["天気","tenki","weather"],["です","desu","is"],["ね","ne","isn’t it"],["。","",""]],"It is nice weather, isn’t it."]
];
